    injectStyle()

    watchPane(BOTS_PANE_ID, scheduleSync)
    watchPane(ROUTINES_PANE_ID, scheduleSync)
    watchStore(host.state?.focusedStoredSessionId || host.state?.activeSessionId, scheduleSync)

